solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <vector>

struct Summary { double min; double max; double median; double p95; double trimmedMean; };

Summary summarise(const std::vector<double>& samples)
{
    if (samples.empty()) return { 0, 0, 0, 0, 0 };
    std::vector<double> s{ samples };
    std::sort(s.begin(), s.end());
    const std::size_t n{ s.size() };

    Summary r{};
    r.min = s.front();
    r.max = s.back();
    r.median = (n % 2 == 1) ? s[n / 2] : (s[n / 2 - 1] + s[n / 2]) / 2.0;

    const auto rank{ static_cast<std::size_t>(std::ceil(0.95 * static_cast<double>(n))) };
    r.p95 = s[rank - 1];

    const std::size_t drop{ n / 10 };
    double total{ 0.0 };
    for (std::size_t i{ drop }; i < n - drop; ++i) total += s[i];
    r.trimmedMean = total / static_cast<double>(n - 2 * drop);
    return r;
}

unitTests:
TEST("odd count")
{
    const auto r{ summarise({ 5, 1, 3 }) };
    CHECK_NEAR(r.min, 1.0, 1e-9); CHECK_NEAR(r.max, 5.0, 1e-9); CHECK_NEAR(r.median, 3.0, 1e-9); CHECK_NEAR(r.p95, 5.0, 1e-9); CHECK_NEAR(r.trimmedMean, 3.0, 1e-9);
}
TEST("even count median") { CHECK_NEAR(summarise({ 4, 1, 3, 2 }).median, 2.5, 1e-9); }
TEST("p95 of twenty")
{
    std::vector<double> v;
    for (int i{ 1 }; i <= 20; ++i) v.push_back(i);
    CHECK_NEAR(summarise(v).p95, 19.0, 1e-9);
}
TEST("an outlier does not move the trimmed mean much")
{
    const std::vector<double> v{ 10, 10, 10, 10, 10, 10, 10, 10, 10, 500 };
    const auto r{ summarise(v) };
    CHECK_NEAR(r.trimmedMean, 10.0, 1e-9);
    CHECK_NEAR(r.median, 10.0, 1e-9);
    CHECK_NEAR(r.max, 500.0, 1e-9);
}
TEST("the input is not modified") { const std::vector<double> v{ 3, 1, 2 }; summarise(v); CHECK_NEAR(v[0], 3.0, 1e-9); }
TEST("empty") { const auto r{ summarise({}) }; CHECK_NEAR(r.median, 0.0, 1e-9); CHECK_NEAR(r.p95, 0.0, 1e-9); }
TEST("one sample") { const auto r{ summarise({ 7 }) }; CHECK_NEAR(r.p95, 7.0, 1e-9); CHECK_NEAR(r.trimmedMean, 7.0, 1e-9); }

